contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 w, uint256 v) external {
        require(address(this).balance >= w + v);
        // deposit w directly into C via its payable fallback
        address(c).call{value: w}("");
        // now drive go(); P must forward v to target AND sweep the leftover w out
        c.go{value: v}();
        assert(address(c).balance == 0);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function t(uint256 amt) external {
        require(address(this).balance > amt + 1);
        // seed the contract with leftover balance via its payable fallback
        uint256 seed = address(this).balance - amt - 1;
        (bool ok, ) = address(c).call{value: seed}("");
        require(ok);
        uint256 before = address(this).balance;
        c.go{value: amt}();
        assert(address(this).balance == before);
    }

    receive() external payable {}
}

