    constructor(C _c) { c = _c; }

    receive() external payable {}
    fallback() external payable {}

    function test(uint extra, uint amount) public {
        require(address(this).balance >= extra + amount);
        require(extra > 0);

        // pre-fund c with extra ether via its payable fallback
        (bool ok1, ) = address(c).call{value: extra}("");
        require(ok1);
        require(address(c).balance == extra);

        c.go{value: amount}();

        // P drains the whole balance; M leaves `extra` behind
        assert(address(c).balance == 0);
    }
}

