contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        require(true);
        // NOTE: this test contract intentionally has NO receive()/payable fallback,
        // so it is an address that cannot accept ETH payouts.
        bool reverted; try c.go() { reverted = false; } catch { reverted = true; }   // boundary
        // Rule: since the leftover balance is always paid to the stored owner
        // (set at C's deployment) and never to the caller, calling go() must
        // succeed even when the caller itself cannot receive Ether.
        // The mutant pays the caller instead, so the payout transfer to this
        // non-receiving contract fails and go() reverts.
        assert(!reverted);
    }
}
